    #[test]
    fn parses_file_exists_check() {
        let yaml = r#"
steps:
  deps:
    command: "yarn install"
    completed_check:
      type: file_exists
      path: "node_modules"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let check = config.steps["deps"].completed_check.as_ref().unwrap();
        assert!(matches!(
