        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    #[test]
    fn rejects_unknown_top_level_fields() {
        let yaml = r#"
app_names: "MyApp"
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo 'app_names' should be rejected");
    }

    #[test]
    fn rejects_unknown_settings_fields() {
        let yaml = r#"
settings:
  log: true
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo 'log' in settings should be rejected");
    }

    #[test]
    fn rejects_unknown_step_fields() {
        let yaml = r#"
steps:
  test:
    commands: "echo test"
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo 'commands' in step should be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_fields() {
        let yaml = r#"
workflows:
  default:
    step: [test]
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "typo 'step' in workflow should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_workflow_settings_fields() {
        let yaml = r#"
workflows:
  ci:
    steps: [test]
    settings:
      noninteractive: true
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "typo 'noninteractive' in workflow settings should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_step_override_fields() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    overrides:
      test:
        skip: true
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "typo 'skip' in step override should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_environment_config_fields() {
        let yaml = r#"
settings:
  environments:
    ci:
      detection:
        - env: CI
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "typo 'detection' in environment config should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_step_environment_override_fields() {
        let yaml = r#"
steps:
  db:
    command: "rails db:setup"
    environments:
      ci:
        commands: "rails db:schema:load"
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "typo 'commands' in step environment override should be rejected"
        );
    }
}

