    commands: "echo test"
"#;
        let result: std::result::Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo 'commands' in step should be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_fields() {
        let yaml = r#"
workflows:
  default:
