        ui.error(&format!("Parse error in {}: {}", path.display(), message));
        return Ok(CommandResult::failure(1));
    }
    Err(BivvyError::ConfigValidationError { message }) => {
        ui.error(&format!("Validation error: {}", message));
        return Ok(CommandResult::failure(1));
    }
    Err(e) => return Err(e),
};

