    #[test]
    fn parses_environment_config() {
        let yaml = r#"
settings:
  environments:
    ci:
      detect:
        - env: CI
        - env: GITHUB_ACTIONS
      default_workflow: ci
      provided_requirements:
        - docker
        - node
    staging:
